import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static int daraja(String turi) {
        if (turi.equals("ram")) return 0;
        if (turi.equals("net")) return 1;
        if (turi.equals("disk")) return 2;
        return 3;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        List<String> nomlar = new ArrayList<>();
        List<Integer> tartib = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            nomlar.add(in.next());
            tartib.add(daraja(in.next()));
        }
        for (int d = 0; d < 4; d++) {
            for (int i = 0; i < n; i++) {
                if (tartib.get(i) == d) {
                    System.out.println(nomlar.get(i));
                }
            }
        }
    }
}

