#include <iostream>
#include <string>
#include <vector>
using namespace std;

int daraja(const string& turi) {
    if (turi == "ram") return 0;
    if (turi == "net") return 1;
    if (turi == "disk") return 2;
    return 3;
}

int main() {
    int n;
    cin >> n;
    vector<string> nomlar(n);
    vector<int> tartib(n);
    for (int i = 0; i < n; i++) {
        string turi;
        cin >> nomlar[i] >> turi;
        tartib[i] = daraja(turi);
    }
    for (int d = 0; d < 4; d++) {
        for (int i = 0; i < n; i++) {
            if (tartib[i] == d) {
                cout << nomlar[i] << endl;
            }
        }
    }
    return 0;
}
